    const [{GravityChartsPlugin}, {settings}, chartkit] = await Promise.all([
        import('@gravity-ui/chartkit/gravity-charts'),
        import('@gravity-ui/chartkit'),
        import('@gravity-ui/chartkit'),
    ]);

    settings.set({plugins: [GravityChartsPlugin]});

